import {
    Table,
    StringColumn,
    ReferenceColumn,
    DomainIdColumn,
    GenericColumn,
    IntegerColumn,
    DomainPathColumn,
} from '../../db'

export const sysrule = Table({
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
        no_labels: true,
        update_synch: false,
    },
    extends: 'sys_metadata',
    extensible: true,
    label: 'Rule',
    name: 'sysrule',
    schema: {
        name: StringColumn({
            label: 'Name',
        }),
        sys_overrides: ReferenceColumn({
            label: [
                {
                    hint: 'Rule being overridden by the current record',
                    label: 'Overrides',
                    plural: 'Overrides',
                },
            ],
            referenceTable: 'sysrule',
        }),
        description: StringColumn({
            label: 'Description',
            maxLength: 4000,
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which the rule belongs',
                    label: 'Domain',
                    plural: 'Domains',
                },
            ],
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        order: IntegerColumn({
            default: '100',
            label: 'Execution Order',
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
        }),
    },
    textIndex: true,
})
